// src/pages/Home.js
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';

const Home = () => {
  const [username, setUsername] = useState('');
  const [roomCode, setRoomCode] = useState('');
  const [isCreating, setIsCreating] = useState(false);
  const [isJoining, setIsJoining] = useState(false);
  const [backendStatus, setBackendStatus] = useState('checking');
  const navigate = useNavigate();

  const API_URL = 'http://localhost:8080';

  useEffect(() => {
    checkBackendStatus();
  }, []);

  const checkBackendStatus = async () => {
    try {
      console.log('Checking backend at:', `${API_URL}/api/rooms/test`);
      const response = await fetch(`${API_URL}/api/rooms/test`);
      if (response.ok) {
        const data = await response.json();
        console.log('Backend response:', data);
        // setBackendStatus('connected');
      } else {
        console.log('Backend responded but not OK');
        // setBackendStatus('disconnected');
      }
    } catch (error) {
      console.error('Backend not reachable:', error);
      // setBackendStatus('disconnected');
    }
  };

  const createRoom = async () => {
    if (!username.trim()) {
      alert('Please enter your good name');
      return;
    }

    setIsCreating(true);
    
    try {
      console.log('Creating room with:', { username: username.trim() });
      const response = await fetch(`${API_URL}/api/rooms/create`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ username: username.trim() }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to create room');
      }

      const data = await response.json();
      console.log('Room created:', data);
      
      localStorage.setItem('userId', data.userId);
      localStorage.setItem('username', data.username);
      localStorage.setItem('role', data.role);
      
      alert(`🎉 Room Created!\n\nRoom Code: ${data.roomId}\n\nShare this code to invite friends!`);
      navigate(`/room/${data.roomId}`);
    } catch (error) {
      console.error('Error creating room:', error);
      alert(`Failed to create room: ${error.message}`);
    } finally {
      setIsCreating(false);
    }
  };

  const joinRoom = async () => {
    if (!username.trim()) {
      alert('Please enter your name!');
      return;
    }
    if (!roomCode.trim()) {
      alert('Please enter a room code!');
      return;
    }

    setIsJoining(true);
    
    try {
      console.log('Joining room:', { roomId: roomCode.toUpperCase(), username: username.trim() });
      const response = await fetch(`${API_URL}/api/rooms/join`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ 
          roomId: roomCode.toUpperCase(), 
          username: username.trim() 
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Room not found');
      }

      const data = await response.json();
      console.log('Joined room:', data);
      
      localStorage.setItem('userId', data.userId);
      localStorage.setItem('username', data.username);
      localStorage.setItem('role', data.role);
      
      alert(`Joined Room: ${roomCode.toUpperCase()}!\n\nYou joined as PARTICIPANT!`);
      navigate(`/room/${roomCode.toUpperCase()}`);
    } catch (error) {
      console.error('Error joining room:', error);
      alert(`${error.message || 'Failed to join room. Please check the room code.'}`);
    } finally {
      setIsJoining(false);
    }
  };

  return (
    <div className="home-container">
      <div className="home-card fade-in-up">
        <div style={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center',
          marginBottom: '15px'
        }}>
          <div style={{ 
            background: backendStatus === 'connected' ? '#4caf50' : '#f44336', 
            padding: '4px 12px', 
            borderRadius: '20px', 
            fontSize: '12px',
            fontWeight: 'bold',
            color: 'white'
          }}>
            {backendStatus === 'connected' ? '✅ Backend Connected' : backendStatus === 'checking' ? '🔄 Checking Backend...' : '❌ Backend Disconnected'}
          </div>
          <button
            onClick={checkBackendStatus}
            style={{
              background: '#667eea',
              border: 'none',
              borderRadius: '20px',
              padding: '4px 12px',
              fontSize: '11px',
              cursor: 'pointer',
              color: 'white'
            }}
          >
          </button>
        </div>
        
        <h1>🎬 YouTube Watch Party</h1>
        <p>Watch YouTube videos together with friends in real-time!</p>
        
        <div className="input-group">
          <input
            type="text"
            placeholder="Enter your name"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && createRoom()}
          />
        </div>

        <div className="action-buttons">
          <button 
            className="btn btn-primary"
            onClick={createRoom}
            disabled={isCreating || backendStatus === 'disconnected'}
          >
            {isCreating ? 'Creating...' : 'Create New Party'}
          </button>
          
          <div className="divider">OR</div>
          
          <div className="join-section">
            <input
              type="text"
              placeholder="Enter room code"
              value={roomCode}
              onChange={(e) => setRoomCode(e.target.value.toUpperCase())}
              onKeyPress={(e) => e.key === 'Enter' && joinRoom()}
            />
            <button 
              className="btn btn-primary"
              onClick={joinRoom}
              disabled={isJoining || backendStatus === 'disconnected'}
            >
              {isJoining ? 'Joining...' : 'Join Party'}
            </button>
          </div>
        </div>

        {backendStatus === 'disconnected' && (
          <div style={{ 
            marginTop: '15px', 
            padding: '10px', 
            background: '#ffebee', 
            borderRadius: '8px', 
            color: '#c62828',
            fontSize: '12px',
            textAlign: 'left'
          }}>
          </div>
        )}

      </div>
    </div>
  );
};

export default Home;
